def solve(g):
    h=len(g); w=len(g[0])
    # stripes: bands of constant i+j, each with one color
    bands={}
    for i in range(h):
        for j in range(w):
            if g[i][j]: bands.setdefault(i+j, g[i][j])
    p=len(bands)
    C={k:v for k,v in sorted(bands.items())}
    seq=[]
    for r in range(p):
        if r not in C:
            # wrap: find k with k mod p == r using largest k
            cand=[k for k in bands if k%p==r]
            seq.append(bands[max(cand)])
        else:
            seq.append(C[r])
    return [[seq[(i+j)%p] for j in range(w)] for i in range(h)]

